const item = $input.first().json.body || $input.first().json;

const proposalId = item.proposalId || item.id || 'PROP-' + Date.now();
const title = item.title || 'Untitled Community Event';
const category = item.category || 'FESTIVAL';
const venue = item.venue || item.venueName || 'Main Grounds / Clubhouse';
const expectedAttendees = Number(item.expectedAttendees || item.capacity || 200);
const estimatedBudget = Number(item.estimatedBudget || item.budget || 25000);
const fundingSource = item.fundingSource || 'SOCIETY_FUND';
const eventStart = item.eventStart || item.startDate || '2026-08-27 18:00';
const eventEnd = item.eventEnd || item.endDate || '2026-08-27 22:30';
const soundLoudspeakersPlanned = item.soundLoudspeakersPlanned ?? true;
const fireOrCookingPlanned = item.fireOrCookingPlanned ?? false;
const organizer = item.organizer || { name: 'Cultural Committee', phone: '', flatNo: '' };

const prompt = `You are the Chief Event Auditor & Safety Compliance Officer for Mana Community Gated Society.
Audit this event proposal before Management Committee (MC) and President approval:

Event Proposal Dossier:
- Proposal ID: ${proposalId}
- Title: ${title}
- Category: ${category}
- Requested Venue: ${venue}
- Expected Attendees: ${expectedAttendees} persons
- Estimated Budget: ₹${estimatedBudget} (Funding: ${fundingSource})
- Timing: From ${eventStart} to ${eventEnd}
- Loudspeakers / Amplified Audio: ${soundLoudspeakersPlanned ? 'YES' : 'NO'}
- Live Cooking / Flame / Pandal Stalls: ${fireOrCookingPlanned ? 'YES' : 'NO'}
- Organizer: ${JSON.stringify(organizer)}

Audit Guidelines:
1. Curfew & Noise: Residential quiet hours strictly start at 10:00 PM. If speakers are used past 10:00 PM, flag as non-compliant or require volume reduction.
2. Fire & Life Safety: If live flame / cooking is planned in temporary pandals, mandate Class B/C fire extinguishers, 6m clear aisle, and local authority notice.
3. Venue Density: Check if venue is suitable for ${expectedAttendees} attendees without blocking emergency exits or resident driveways.
4. Budget Health: Check if cost per attendee (₹${Math.round(estimatedBudget / Math.max(1, expectedAttendees))}/head) is viable, and whether contingency reserve is adequate.
5. Recommendation: Provide one of [APPROVED, CONDITIONAL_APPROVAL, REVISION_REQUIRED, REJECTED] with clear rationale.

Respond ONLY with a valid JSON object matching this schema:
{
  "screeningVerdict": "APPROVED" | "CONDITIONAL_APPROVAL" | "REVISION_REQUIRED" | "REJECTED",
  "viabilityScore": number (0 to 100),
  "budgetHealth": {
    "feasibility": "FEASIBLE" | "UNDERBUDGETED" | "RISKY",
    "costPerHead": number,
    "notes": string
  },
  "safetyCompliance": {
    "curfewCompliant": boolean,
    "fireClearanceRequired": boolean,
    "crowdDensityRisk": "LOW" | "MODERATE" | "HIGH",
    "noiseAdvisory": string
  },
  "permitRequirements": string[],
  "committeeRecommendation": string
}`;

return [{ json: { prompt, proposalId, title, expectedAttendees, estimatedBudget } }];

const raw = $input.first().json;
let parsed;

try {
  const content = raw.candidates?.[0]?.content?.parts?.[0]?.text;
  if (content) {
    const cleaned = content.replace(/^\s*\`\`\`json\s*|\s*\`\`\`\s*$/g, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (e) {}

if (!parsed || !parsed.screeningVerdict) {
  const budget = raw.estimatedBudget || 25000;
  const attendees = raw.expectedAttendees || 200;
  const costPerHead = Math.round(budget / Math.max(1, attendees));
  parsed = {
    screeningVerdict: "CONDITIONAL_APPROVAL",
    viabilityScore: 84,
    budgetHealth: {
      feasibility: costPerHead < 500 ? "FEASIBLE" : "RISKY",
      costPerHead: costPerHead,
      notes: "Standard society festive allocation within typical parameters."
    },
    safetyCompliance: {
      curfewCompliant: true,
      fireClearanceRequired: false,
      crowdDensityRisk: attendees > 300 ? "MODERATE" : "LOW",
      noiseAdvisory: "Loudspeaker levels must be reduced below 55dB after 9:30 PM."
    },
    permitRequirements: [
      "Estate Manager Venue Clearance",
      "Security Gate Headcount Log"
    ],
    committeeRecommendation: "Recommended for conditional approval subject to compliance with residential quiet hours."
  };
}

return [{
  json: {
    status: "success",
    proposalId: raw.proposalId,
    eventTitle: raw.title,
    evaluatedAt: new Date().toISOString(),
    evaluation: parsed
  }
}];
